'use strict';

const javaio = require('java.io');
const Constants = javaio.constants;
const utility = require('utility');
const NProtocolPacket = require('./NProtocolPacket');
const NVersionElement = require('./NVersionElement');

module.exports = create;

const ATTRIBUTES = {
  dataId: 'data_id',
  scope: '!scope',
  groupId: 'group_id',
  elementtype: '!elementtype',
  appName: '!AppName',
  appSign: '!AppSign',
  clientId: 'client_id',
  instanceId: 'instance_id',
};

function create(pkg) {
  pkg = pkg || {};
  const elements = [ NVersionElement.CURRENT ];
  if (pkg.regPacket) {
    elements.push(pkg.regPacket);
  }
  const attribute = {};
  for (const key in ATTRIBUTES) {
    const realKey = ATTRIBUTES[key];
    if (pkg[key]) {
      attribute[realKey] = pkg[key];
    }
  }

  const { accessKey, accessSecret, instanceId } = pkg;
  if (accessKey && accessSecret && instanceId) {
    const cacheTime = 5 * 60 * 1000;
    const timestamp = String(Math.round(Date.now() / cacheTime) * cacheTime);

    attribute['!AccessKey'] = accessKey;
    attribute['!Algorithm'] = 'HmacSHA256';
    attribute['!Signature'] = utility.hmac('sha256', accessSecret, instanceId + timestamp, 'base64');
    attribute['!Timestamp'] = timestamp;
  }
  return {
    $: {
      elements,
      connId: null,
      ids: null,
      ispushed: true,
      isTempElement: false,
      timeStamp: pkg.timeStamp,
      attribute: {
        $: { loadFactor: 0.75, threshold: 12 },
        $class: {
          name: 'java.util.HashMap',
          serialVersionUID: '362498820763181265',
          flags: 3,
          fields: [{ type: 'F', name: 'loadFactor' },
            { type: 'I', name: 'threshold' },
          ],
          superClass: null,
        },
        _$: attribute,
      },
    },
    $class: {
      name: 'com.alipay.config.common.protocol.NProtocolPackageMulti',
      serialVersionUID: '-7676658119572392587',
      flags: 3,
      fields: [],
      superClass: {
        name: 'com.alipay.config.common.protocol.NProtocolPackage',
        serialVersionUID: '1',
        flags: 2,
        fields: [],
        superClass: {
          name: 'com.alipay.config.common.protocol.NProtocolPacket',
          serialVersionUID: '-3491248796286893704',
          flags: 3,
          fields: [{ type: 'Z', name: 'isTempElement' },
            { type: 'Z', name: 'ispushed' },
            { type: 'J', name: 'timeStamp' },
            { type: 'L', name: 'attribute', classname: 'Ljava/util/Map;' },
            { type: 'L', name: 'connId', classname: 'Ljava/lang/String;' },
            { type: '[', name: 'ids', classname: '[[Ljava/lang/String;' },
          ],
          superClass: null,
        },
      },
    },
  };
}

javaio.addObject('com.alipay.config.common.protocol.NProtocolPackageMulti', {
  readObject(io, obj) {
    NProtocolPacket.readObject(io, obj);
    // skip TC_ENDBLOCKDATA
    io.in.get();
    // TODO: WTF, readObject again?!
    // this$0
    NProtocolPacket.readObject(io, obj);
    obj.$.attribute = io.readObject();
  },
  writeObject(io, obj) {
    NProtocolPacket.writeObject(io, obj);
    io.out.put(Constants.TC_ENDBLOCKDATA);
    NProtocolPacket.writeObject(io, obj);
    io.writeObject(obj.$.attribute);
  },
});
